use ark_ec::{AffineRepr,CurveGroup};use ark_ff::PrimeField;
fn fq(b:&[u8])->ark_bn254::Fq{ark_bn254::Fq::from_le_bytes_mod_order(b)}
fn main(){let mut total=[0;2];for n in[0usize,1,7,8,9,31,32,200,352,1023,1024,1025]{for g2 in[false,true]{let bytes=zopro_core::formation_oracle_records(g2,n);let size=if g2{128}else{64};assert_eq!(bytes.len(),2*n*size);for i in 0..n{let a=&bytes[i*size..(i+1)*size];let b=&bytes[(n+i)*size..(n+i+1)*size];if g2{let decode=|v:&[u8]|if v.iter().all(|b|*b==0){ark_bn254::G2Affine::identity()}else{ark_bn254::G2Affine::new_unchecked(ark_bn254::Fq2::new(fq(&v[..32]),fq(&v[32..64])),ark_bn254::Fq2::new(fq(&v[64..96]),fq(&v[96..128])))};let a=decode(a);let b=decode(b);assert!(a.is_on_curve()&&a.is_in_correct_subgroup_assuming_on_curve());assert!(b.is_on_curve()&&b.is_in_correct_subgroup_assuming_on_curve());assert_eq!((a.into_group()*ark_bn254::Fr::from(3u64)).into_affine(),b);}else{let decode=|v:&[u8]|if v.iter().all(|b|*b==0){ark_bn254::G1Affine::identity()}else{ark_bn254::G1Affine::new_unchecked(fq(&v[..32]),fq(&v[32..]))};let a=decode(a);let b=decode(b);assert!(a.is_on_curve()&&b.is_on_curve());assert_eq!((a.into_group()*ark_bn254::Fr::from(3u64)).into_affine(),b);}total[usize::from(g2)]+=1;}}}println!("ARK_ORACLE_PASS G1={} G2={} input/output oncurve/subgroup G2;empty/tails/identity/sign/fulltile;no SDKproof",total[0],total[1]);}
